<script>
  const {
    class: klass = '',
    title,
    titleClass,
    active,
    children,
    ...rest
  } = $props()
</script>

<button
  {...rest}
  class="tab {title && 'vertical'} {klass}"
  aria-selected={active}
  role="tab"
>
  {#if title}
    <span class="tab-title {titleClass}">{title}</span>
  {/if}
  {@render children?.()}
</button>
